/**
 * Hero banner, two builds switched with mso conditional comments:
 *  - Modern clients (Gmail, Apple Mail, iOS, new Outlook, OWA): a live HTML banner (category chip, rose live dot,
 *    tagline and feature labels are real text) with an animated GIF strip of the five feature icons
 *    (600x76, 16 frames, ~71 KB, no text in the image). Icons sit at ~40% opacity with a slow shimmer
 *    and a drifting waveform; frame 1 is complete because some clients show only the first frame.
 *  - Outlook desktop (Word engine) and images-off: the same banner from tables only, with a VML gradient and
 *    dim unicode glyphs in tinted cells instead of the GIF, so it looks complete with zero images loaded.
 * Icons are Lucide (ISC, already a web dependency); generated outside the repo with headless Chromium + Pillow.
 */
export type BannerCategory = 'security' | 'workspace' | 'meeting' | 'tasks' | 'integration';

export const BANNER_WIDTH = 600;
export const BANNER_HEIGHT = 76;
/** Solid fallback colour of the banner cell when images are blocked. */
export const BANNER_FALLBACK = '#0D0D10';
export const BANNER_CID = 'meetops-banner@meetops';

export const bannerGif =
  '';
